  function rarityName(item){const raw=item.rarity||'Yaygın';return raw==='Sıradan'||raw==='Common'?'Yaygın':raw==='Rare'?'Nadir':raw==='Epic'?'Destansı':raw==='Legendary'?'Efsanevi':raw}
